let docs = Array.isArray(msg.payload) ? msg.payload : [];

docs = docs.filter(doc => doc && doc.tipo === "ponto_recarga" && doc.ativo === true);

msg.payload = docs.map(doc => ({
    id: doc._id,
    nome: doc.nome,
    status: doc.status,
    ocupado: doc.ocupado === true,
    ocupado_em: doc.ocupado_em || null,
    latitude: doc.latitude,
    longitude: doc.longitude,
    endereco: doc.endereco,
    conectores: doc.conectores || [],
    servicos: doc.servicos || [],
    ultima_atualizacao: doc.ultima_atualizacao
}));

return msg;

let docs = Array.isArray(msg.payload) ? msg.payload : [];

docs = docs.filter(doc => doc && doc.tipo === "veiculo");

msg.payload = docs.map(doc => ({
    id: doc._id,
    marca: doc.marca,
    modelo: doc.modelo,
    conectores_compativeis: doc.conectores_compativeis || [],
    potencia_max_suportada_kw: doc.potencia_max_suportada_kw
}));

return msg;

let docs = Array.isArray(msg.payload) ? msg.payload : [];
let veiculoId = msg.req.params.veiculo_id;

let veiculo = docs.find(doc => doc && doc._id === veiculoId && doc.tipo === "veiculo");

if (!veiculo) {
    msg.statusCode = 404;
    msg.payload = { erro: "Veículo não encontrado" };
    return msg;
}

let pontos = docs.filter(doc => doc && doc.tipo === "ponto_recarga" && doc.ativo === true);
let conectoresCompativeis = veiculo.conectores_compativeis || [];
let potenciaMax = Number(veiculo.potencia_max_suportada_kw || 0);

let compativeis = pontos.filter(ponto =>
    (ponto.conectores || []).some(c =>
        conectoresCompativeis.includes(c.tipo) &&
        Number(c.potencia_kw) <= potenciaMax
    )
);

msg.payload = {
    veiculo: {
        id: veiculo._id,
        marca: veiculo.marca,
        modelo: veiculo.modelo
    },
    pontos_compativeis: compativeis.map(ponto => ({
        id: ponto._id,
        nome: ponto.nome,
        status: ponto.status,
        latitude: ponto.latitude,
        longitude: ponto.longitude,
        endereco: ponto.endereco,
        conectores: ponto.conectores || [],
        servicos: ponto.servicos || [],
        ultima_atualizacao: ponto.ultima_atualizacao
    }))
};

return msg;

let body = msg.payload;

if (!body || !body.ponto_id || !body.campo_sugerido || !body.valor_sugerido) {
    msg.statusCode = 400;
    msg.payload = {
        erro: "Campos obrigatórios não informados",
        obrigatorios: ["ponto_id", "campo_sugerido", "valor_sugerido"]
    };
    return [null, msg];
}

msg.payload = {
    _id: "correcao_" + Date.now(),
    tipo: "sugestao_correcao",
    ponto_id: body.ponto_id,
    campo_sugerido: body.campo_sugerido,
    valor_sugerido: body.valor_sugerido,
    descricao: body.descricao || "",
    data_envio: new Date().toISOString(),
    status_revisao: "pendente"
};

return [msg, null];

msg.statusCode = 201;
msg.payload = {
    mensagem: "Sugestão enviada com sucesso"
};
return msg;

let novaMsg = {
    filtros: (msg.req && msg.req.query) ? msg.req.query : {},
    res: msg.res
};

return novaMsg;

let docs = Array.isArray(msg.payload) ? msg.payload : [];
let q = msg.filtros || {};

let pontos = docs.filter(doc => doc && doc.tipo === "ponto_recarga" && doc.ativo === true);

if (q.status) {
    pontos = pontos.filter(p =>
        String(p.status).toLowerCase() === String(q.status).toLowerCase()
    );
}

if (q.conector) {
    pontos = pontos.filter(p =>
        (p.conectores || []).some(c =>
            String(c.tipo).toLowerCase() === String(q.conector).toLowerCase()
        )
    );
}

if (q.potencia_min) {
    let min = Number(q.potencia_min);
    pontos = pontos.filter(p =>
        (p.conectores || []).some(c => Number(c.potencia_kw) >= min)
    );
}

if (q.servico) {
    pontos = pontos.filter(p =>
        (p.servicos || []).some(s =>
            String(s).toLowerCase() === String(q.servico).toLowerCase()
        )
    );
}

msg.payload = pontos.map(ponto => ({
    id: ponto._id,
    nome: ponto.nome,
    status: ponto.status,
    latitude: ponto.latitude,
    longitude: ponto.longitude,
    endereco: ponto.endereco,
    conectores: ponto.conectores || [],
    servicos: ponto.servicos || [],
    ultima_atualizacao: ponto.ultima_atualizacao
}));

return msg;

let novaMsg = {
    ponto_id: msg.req && msg.req.params ? msg.req.params.id : null,
    res: msg.res
};

return novaMsg;

let docs = Array.isArray(msg.payload) ? msg.payload : [];
let pontoId = msg.ponto_id;

let ponto = docs.find(doc => doc && doc._id === pontoId && doc.tipo === "ponto_recarga");

if (!ponto) {
    msg.statusCode = 404;
    msg.payload = { erro: "Ponto não encontrado" };
    return msg;
}

msg.payload = {
    id: ponto._id,
    nome: ponto.nome,
    descricao: ponto.descricao || "",
    status: ponto.status,
    ocupado: ponto.ocupado === true,
    ocupado_em: ponto.ocupado_em || null,
    latitude: ponto.latitude,
    longitude: ponto.longitude,
    endereco: ponto.endereco,
    conectores: ponto.conectores || [],
    servicos: ponto.servicos || [],
    ultima_atualizacao: ponto.ultima_atualizacao,
    ativo: ponto.ativo
};

return msg;

let body = msg.payload;

if (!body || !body.nome || body.latitude === undefined || body.longitude === undefined || !body.endereco) {
    msg.statusCode = 400;
    msg.payload = {
        erro: "Campos obrigatórios não informados",
        obrigatorios: ["nome", "latitude", "longitude", "endereco"]
    };
    return [null, msg];
}

msg.payload = {
    _id: "ponto_" + Date.now(),
    tipo: "ponto_recarga",
    nome: body.nome,
    descricao: body.descricao || "",
    status: body.status || "funcionando",
    latitude: Number(body.latitude),
    longitude: Number(body.longitude),
    endereco: body.endereco,
    conectores: Array.isArray(body.conectores) ? body.conectores : [],
    servicos: Array.isArray(body.servicos) ? body.servicos : [],
    ultima_atualizacao: new Date().toISOString(),
    ativo: true,
    ocupado: false,
    ocupado_em: null
};

return [msg, null];

msg.statusCode = 201;
msg.payload = { mensagem: "Ponto criado com sucesso" };
return msg;

return {
    ponto_id: msg.req?.params?.id || null,
    body: msg.payload || {},
    res: msg.res
};

let docs = Array.isArray(msg.payload) ? msg.payload : [];
let pontoId = msg.ponto_id;
let body = msg.body || {};

let ponto = docs.find(doc => doc && doc._id === pontoId && doc.tipo === "ponto_recarga");

if (!ponto) {
    msg.statusCode = 404;
    msg.payload = { erro: "Ponto não encontrado" };
    return [null, msg];
}

let atualizado = {
    ...ponto,
    nome: body.nome ?? ponto.nome,
    descricao: body.descricao ?? ponto.descricao,
    status: body.status ?? ponto.status,
    latitude: body.latitude !== undefined ? Number(body.latitude) : ponto.latitude,
    longitude: body.longitude !== undefined ? Number(body.longitude) : ponto.longitude,
    endereco: body.endereco ?? ponto.endereco,
    conectores: Array.isArray(body.conectores) ? body.conectores : ponto.conectores,
    servicos: Array.isArray(body.servicos) ? body.servicos : ponto.servicos,
    ativo: body.ativo !== undefined ? Boolean(body.ativo) : ponto.ativo,
    ocupado: body.ocupado !== undefined ? Boolean(body.ocupado) : (ponto.ocupado === true),
    ocupado_em: body.ocupado === false ? null : (body.ocupado_em !== undefined ? body.ocupado_em : (ponto.ocupado_em || null)),
    ultima_atualizacao: new Date().toISOString()
};

msg.payload = atualizado;
return [msg, null];

return {
    ponto_id: msg.req?.params?.id || null,
    res: msg.res
};

let docs = Array.isArray(msg.payload) ? msg.payload : [];
let pontoId = msg.ponto_id;

let ponto = docs.find(doc => doc && doc._id === pontoId && doc.tipo === "ponto_recarga");

if (!ponto) {
    msg.statusCode = 404;
    msg.payload = { erro: "Ponto não encontrado" };
    return [null, msg];
}

if (ponto.status === "manutencao") {
    msg.statusCode = 409;
    msg.payload = { erro: "Ponto em manutenção" };
    return [null, msg];
}

if (ponto.ocupado === true) {
    msg.statusCode = 409;
    msg.payload = { erro: "Ponto já está ocupado" };
    return [null, msg];
}

msg.payload = {
    ...ponto,
    ocupado: true,
    ocupado_em: new Date().toISOString(),
    ultima_atualizacao: new Date().toISOString()
};

return [msg, null];

return {
    ponto_id: msg.req?.params?.id || null,
    res: msg.res
};

let docs = Array.isArray(msg.payload) ? msg.payload : [];
let pontoId = msg.ponto_id;

let ponto = docs.find(doc => doc && doc._id === pontoId && doc.tipo === "ponto_recarga");

if (!ponto) {
    msg.statusCode = 404;
    msg.payload = { erro: "Ponto não encontrado" };
    return [null, msg];
}

if (ponto.ocupado !== true) {
    msg.statusCode = 409;
    msg.payload = { erro: "Ponto já está desocupado" };
    return [null, msg];
}

msg.payload = {
    ...ponto,
    ocupado: false,
    ocupado_em: null,
    ultima_atualizacao: new Date().toISOString()
};

return [msg, null];
